__attribute__((import_module("engine.random@1"), import_name("f32")))
float engine_random_f32(void);

/**
 * A pseudo-random integer in `0 <= x < n` (0 when `n <= 0`).
 * Index signature: `(n: i64) -> (x: i64)`.
 */
__attribute__((import_module("engine.random@1"), import_name("range")))
int64_t engine_random_range(int64_t n);

/**
 * Restart the stream from `seed` (the same seed gives the same numbers).
 * Index signature: `(seed: i64)`.
 */
__attribute__((import_module("engine.random@1"), import_name("seed")))
void engine_random_seed(int64_t seed);

/** Per-entity scripts. The `Script` component is Rust-only, so this is how a script attaches one of its own entry functions to an entity. */
#define ENGINE_SCRIPT_VERSION 1

/**
 * Queue attaching a `Script` to `entity`: every frame the engine calls the calling module's exported function `entry(entity: i64, dt: f32, state: i64) -> i64` for it, the result being the next `state` (0 at first). Applied after the stage, replaces an existing `Script`. Status: 0 ok, 1 stale entity, 2 the module has no export `entry` of that signature, 3 no module is running.
 * Index signature: `(entity: entity, entry: str) -> (status: i32)`.
 */
__attribute__((import_module("engine.script@1"), import_name("attach")))
int32_t engine_script_attach(efe_entity entity, const char* entry_ptr, size_t entry_len);

/** Frame timing. */
#define ENGINE_TIME_VERSION 1

/**
 * Seconds since the previous frame.
 * Index signature: `() -> (seconds: f32)`.
 */
__attribute__((import_module("engine.time@1"), import_name("delta")))
float engine_time_delta(void);

/**
 * Seconds since the engine started.
 * Index signature: `() -> (seconds: f64)`.
 */
__attribute__((import_module("engine.time@1"), import_name("elapsed")))
double engine_time_elapsed(void);

/**
 * Length of a fixed update step in seconds.
 * Index signature: `() -> (seconds: f32)`.
 */
__attribute__((import_module("engine.time@1"), import_name("fixed_delta")))
float engine_time_fixed_delta(void);

/**
 * Number of frames run so far.
 * Index signature: `() -> (frame: i64)`.
 */
__attribute__((import_module("engine.time@1"), import_name("frame")))
int64_t engine_time_frame(void);

/** Entities and their components. Entity handles are u64 values; a stale or forged handle gives status 1, never a crash. */
#define ENGINE_WORLD_VERSION 1

/**
 * 1 if `entity` exists (spawned and not despawned), else 0.
 * Index signature: `(entity: entity) -> (alive: bool)`.
 */
__attribute__((import_module("engine.world@1"), import_name("alive")))
bool engine_world_alive(efe_entity entity);

/**
 * 1 if component `component` of `entity` was added or changed after tick `since` (from `engine.world.tick`), 0 if not. A component whose type does not track changes always reports 1. Buffered writes are applied after the stage, so a module's own writes show up as changed on the next frame. Negative status: -1 stale entity, -2 component missing, -3 unknown component id.
 * Index signature: `(entity: entity, component: i32, since: i32) -> (status: i32)`.
 */
__attribute__((import_module("engine.world@1"), import_name("changed")))
int32_t engine_world_changed(efe_entity entity, int32_t component, int32_t since);

/**
 * The id of the component named `name` (`Transform`, `Velocity`, ...), or -1 if there is no such component. The same ids are in the API index.
 * Index signature: `(name: str) -> (id: i32)`.
 */
__attribute__((import_module("engine.world@1"), import_name("component_id")))
int32_t engine_world_component_id(const char* name_ptr, size_t name_len);

/**
 * Queue despawning `entity` (applied after the stage). Status: 0 ok, 1 stale entity.
 * Index signature: `(entity: entity) -> (status: i32)`.
 */
__attribute__((import_module("engine.world@1"), import_name("despawn")))
int32_t engine_world_despawn(efe_entity entity);

/**
 * Copy component `component` (an id from component_id or the index) of `entity` to `out`, which must have room for the component's size. Reads the start-of-frame value, except that a module sees its own earlier `set`s of this frame. Status: 0 ok, 1 stale entity, 2 component missing, 3 unknown component id.
 * Index signature: `(entity: entity, component: i32, out: ptr) -> (status: i32)`.
 */
__attribute__((import_module("engine.world@1"), import_name("get")))
int32_t engine_world_get(efe_entity entity, int32_t component, void* out);

/**
 * 1 if `entity` is alive and has component `component`, else 0 (also for an unknown component id).
 * Index signature: `(entity: entity, component: i32) -> (has: bool)`.
 */
__attribute__((import_module("engine.world@1"), import_name("has")))
bool engine_world_has(efe_entity entity, int32_t component);

/**
 * Queue adding (or replacing) component `component` on `entity` from the bytes at `src` (the component's size); applied after the stage. Status: 0 ok, 1 stale entity, 3 unknown component id, 5 read-only component.
 * Index signature: `(entity: entity, component: i32, src: ptr) -> (status: i32)`.
 */
__attribute__((import_module("engine.world@1"), import_name("insert")))
int32_t engine_world_insert(efe_entity entity, int32_t component, void* src);

/**
 * Write the handles (u64, 8 bytes each) of entities that have component `component` to `out`, at most `cap` of them, and return how many were written; -1 for an unknown component id.
 * Index signature: `(component: i32, out: ptr, cap: i64) -> (count: i64)`.
 */
__attribute__((import_module("engine.world@1"), import_name("query")))
int64_t engine_world_query(int32_t component, void* out, int64_t cap);

/**
 * Queue removing component `component` from `entity`; applied after the stage (a missing component is ignored then). Status: 0 ok, 1 stale entity, 3 unknown component id, 5 read-only component.
 * Index signature: `(entity: entity, component: i32) -> (status: i32)`.
 */
__attribute__((import_module("engine.world@1"), import_name("remove")))
int32_t engine_world_remove(efe_entity entity, int32_t component);

/**
 * Overwrite, in place, the existing component `component` of `entity` with the bytes at `src` (the component's size). Buffered: applied after all scripts of the frame ran, in module order (a later module wins over an earlier one); the calling module reads its own write back at once, other modules see the old value until next frame. Status: 0 ok, 1 stale entity, 2 component missing, 3 unknown component id, 5 read-only component.
 * Index signature: `(entity: entity, component: i32, src: ptr) -> (status: i32)`.
 */
__attribute__((import_module("engine.world@1"), import_name("set")))
int32_t engine_world_set(efe_entity entity, int32_t component, void* src);

/**
 * Take a new empty entity from the calling module's pre-reserved pool and return its handle; it is valid at once and comes alive when the frame's commands apply (add components with insert). When the pool is empty (more spawns in one frame than reserved; the pool grows for the next frame) the null handle 0 is returned, which every function treats as a stale entity.
 * Index signature: `() -> (entity: entity)`.
 */
__attribute__((import_module("engine.world@1"), import_name("spawn")))
efe_entity engine_world_spawn(void);

/**
 * The current change tick (the script system's tick this frame). Store it and pass it to `changed` next frame.
 * Index signature: `() -> (tick: i32)`.
 */
__attribute__((import_module("engine.world@1"), import_name("tick")))
int32_t engine_world_tick(void);

